insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.1', 'Origem do UPALELE', 'O UPALELE foi criado em 2014; o criador é identificado no memorial como c L as H eiro.', true, 11) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.2', 'Tomada de decisão', 'Os colíderes decidem por votação, inclusive promoções e penalidades. O líder não vota, salvo quando o número de colíderes é par; nesse caso, seu voto é o último e decisivo.', true, 12) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.3', 'Atualização das regras', 'As regras podem ser revistas em momento oportuno, conforme a evolução do clã.', true, 13) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.4', 'Visão do clã', 'O UPALELE busca evolução contínua sem arbitrariedade, com decisões coletivas e justiça não unilateral.', true, 14) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.5', 'Atividade dos membros', 'O membro deve ser ativo: doações, guerras, liga, jogos do clã ou raide. Deve contribuir de alguma forma.', true, 15) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.6', 'Inatividade temporária', 'Quem precisar ficar inativo por demandas da vida deve informar a liderança para evitar banimento.', true, 16) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Ideologia', '1.7', 'Saída do clã', 'A saída não é permitida, exceto para campeonato com autorização prévia ou Liga de Guerra em outro clã, respeitando as regras de saída e retorno.', true, 17) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.1', 'Participação em guerra', 'A participação em guerra não é obrigatória.', true, 21) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.2', 'Heróis ativos', 'É obrigatório ter 4 heróis ativos.', true, 22) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.3', 'Doações no mapa', 'As doações no mapa são feitas pela liderança.', true, 23) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.4', 'Primeira participação', 'Na primeira guerra normal ou liga, é necessário ler e confirmar as orientações enviadas pelo WhatsApp, pois contêm a estratégia.', true, 24) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.5', 'Seleção para guerras seguintes', 'Após a primeira participação, a liderança seleciona o membro com base na cor do perfil.', true, 25) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.6', 'Horário dos ataques', 'Sempre que possível, atacar nas primeiras 12 horas.', true, 26) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.7', 'Castelo incompleto ou ataque não realizado', 'Quem atacar com castelo incompleto (tropa, feitiço ou cerco) ou não realizar primeiro/segundo ataque quando aplicável será punido.', true, 27) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.8', 'Ataque para bônus', 'Se todas as vilas do mapa já tiverem 3 estrelas, o ataque para bônus é liberado.', true, 28) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.9', 'Alvo sendo atacado', 'Se outro membro estiver atacando seu alvo, espere o término; ataque depois se o alvo ainda não tiver 3 estrelas.', true, 29) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.10', 'Seleção quando o número não fecha', 'Se o número de membros não for exato, podem ficar de fora os que atacam por último ou apresentam pior performance (heróis inativos). Na guerra seguinte retornam; o memorial diz que isso não é castigo.', true, 210) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.11', 'Múltiplas contas de novatos', 'Primeiro participa a conta do novato com CV mais forte; depois, as demais.', true, 211) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Guerra de clã', '2.12', 'Problemas extraordinários', 'Reportar o quanto antes pelo WhatsApp para realocar ataques e evitar punição. Se não foi possível avisar antes, procurar líder ou colíder em privado para avaliar o retorno.', true, 212) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.14', 'Primeiro ataque', 'Atacar dois alvos abaixo do espelho. Exemplo do memorial: posição 2 ataca posição 4.', true, 214) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.15', 'Alvo atacado com estrela disponível', 'Se a vila já foi atacada mas ainda tem estrela disponível, atacá-la para tentar completar as 3 estrelas.', true, 215) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.16', 'Alvo com três estrelas', 'Se a vila tem 3 estrelas, descer para a vila abaixo com estrela disponível.', true, 216) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.17', 'Todas as vilas abaixo fechadas', 'Se todas as vilas abaixo têm 3 estrelas, subir e atacar a primeira vila com estrela disponível.', true, 217) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.18', 'Segundo ataque', 'Atacar o oponente do mesmo nível de CV mais abaixo no mapa com estrela disponível.', true, 218) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.19', 'Sem CV igual disponível', 'Se não houver oponente do mesmo CV disponível, atacar CV inferior, de baixo para cima.', true, 219) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Estratégia de guerra', '2.20', 'Sem CV igual ou inferior', 'Se não houver CV igual ou inferior disponível, atacar CV superior, de baixo para cima, com estrela disponível.', true, 220) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.1', 'Participação na liga', 'A participação na Liga de Guerra não é obrigatória.', true, 31) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.2', 'Heróis ativos', 'É obrigatório ter 4 heróis ativos.', true, 32) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.3', 'Estratégia da liga', 'A estratégia é atacar o espelho.', true, 33) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.4', 'Participação para medalhas', 'Todos os membros são levados para que possam ganhar medalhas.', true, 34) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.4.1', 'Titulares da primeira guerra', 'O líder define quem inicia considerando CV, performance ofensiva anterior e potencial defensivo.', true, 341) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.5', 'Elegibilidade para o mapa', 'Para iniciar no mapa, o membro precisa ter participado de pelo menos uma guerra normal; caso contrário, entra na lista de revezamento.', true, 35) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.6', 'Múltiplas contas', 'Primeiro participa a conta com CV mais forte e, posteriormente, as demais.', true, 36) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.7', 'Revezamento após duas estrelas', 'Caso o jogador consiga 2 estrelas, revezará com membros da reserva.', true, 37) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.7.1', 'Substituições', 'O líder pode fazer as substituições que considerar necessárias durante a liga.', true, 371) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.8', 'Alvo atacado equivocadamente', 'Atacar o espelho de quem atacou seu alvo.', true, 38) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.9', 'Troca de alvo', 'É permitido trocar de alvo se autorizado/combinado pelo chat ou WhatsApp.', true, 39) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.10', 'Prazo de ataque', 'Sempre que possível, atacar nas primeiras 12 horas. Nas últimas 2 horas, a liderança substitui quem não atacou; o membro vai para a fila de revezamento.', true, 310) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.11', 'Medalhas extras', 'As medalhas extras são dadas aos jogadores que conquistarem mais estrelas.', true, 311) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.12', 'Medalhas em múltiplas contas', 'Membros com mais de um CV recebem medalhas extras em apenas uma vila e escolhem qual conta, mesmo que não tenha conquistado meritocracia.', true, 312) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.13', 'Saída para jogar liga em outro clã', 'Membros não selecionados entre 15 titulares e 5 reservas podem sair para jogar liga em outro clã; o secundário é sugerido.', true, 313) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Liga de guerra', '3.14', 'Período de saída e retorno', 'Saída entre dia 29 do mês anterior e dia 31; retorno entre dias 8 e 11. O memorial não permite fora desses períodos.', true, 314) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Raide', '4.1', 'Participação na raide', 'A participação é obrigatória.', true, 41) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Raide', '4.2', 'Ouro da Capital', 'Doar para melhorias marcadas como prioridade ou destinadas à Torre do Tesouro.', true, 42) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Raide', '4.3', 'Ordem de ataques', 'Não há ordem de ataque ou estratégia específica.', true, 43) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Raide', '4.4', 'Ataques e recursos', 'Mesmo com melhorias completas, fazer ataques para subir de liga e acumular recursos na Torre do Tesouro.', true, 44) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Raide', '4.5', 'Destino do ouro', 'O ouro deve ir para a Torre do Tesouro ou para o clã secundário, somente aos domingos.', true, 45) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Jogos do clã', '5.1', 'Participação nos jogos', 'A participação é obrigatória.', true, 51) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Jogos do clã', '5.2', 'Recompensas coletivas', 'A conclusão coletiva dos pontos é fundamental para resgatar todas as recompensas.', true, 52) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Jogos do clã', '5.3', 'Recompensa extra', 'Quem atingir 4.000 pontos individuais ganha a recompensa extra.', true, 53) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Push', '6.1', 'Participação no push', 'O push será feito de forma não obrigatória para dar visibilidade ao clã e proporcionar novas experiências.', true, 61) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('WhatsApp', '7.1', 'Participação no grupo', 'A participação no grupo de WhatsApp não é obrigatória.', true, 71) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('WhatsApp', '7.2', 'Eventos de guerra', 'Para participar de eventos de guerra, é obrigatório estar no grupo onde a estratégia é repassada.', true, 72) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('WhatsApp', '7.3', 'Identificação', 'Ao entrar no grupo, inserir no apelido o nick usado no jogo.', true, 73) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('WhatsApp', '7.4', 'Argumentação após banimento', 'Após banimento por ausência de ataque ou outra infração, o jogador apresenta argumentos pelo aplicativo.', true, 74) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('WhatsApp', '7.5', 'Avaliação de retorno', 'O membro banido deve expor sua situação ao líder/colíder pelo WhatsApp para avaliação do retorno e cargo.', true, 75) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Doações', '8.1', 'Quantidade de doações', 'Não existe regra de quantidade de doações.', true, 81) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Doações', '8.3', 'Equilíbrio e atividade', 'Equilibrar doações quando possível. Os índices demonstram atividade, mas não há número obrigatório.', true, 83) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Doações', '8.4', 'Doações recebidas', 'O membro não deve se preocupar com saldo negativo; o foco é gerar XP para o clã.', true, 84) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.1', 'Promoção a ancião', 'O líder promove considerando atividade, doações, raide, jogos, eventos e principalmente guerras.', true, 91) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.2', 'Recrutamento', 'Anciões devem compartilhar o link do clã com grupos e jogadores que atendam ao perfil.', true, 92) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.3', 'Aceitar membros', 'Requisitos informados: CV mínimo 17, Rei e Rainha nível 100 e 1.000 estrelas de guerra. Ao rejeitar, justificar o critério.', true, 93) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.4', 'Expulsar membros fora dos requisitos', 'Anciões podem expulsar quem não atende aos requisitos mínimos; justificar o motivo.', true, 94) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.5', 'Orientação a novos membros', 'Perguntar se pretende ir a guerras, explicar a exigência do WhatsApp para eventos de guerra e encaminhar contato à liderança.', true, 95) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.6', 'Membros antigos que saíram', 'Anciões não devem aceitar membros antigos que saiam do clã.', true, 96) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order) values ('Anciões', '9.7', 'Ofensas no chat', 'Anciões podem expulsar membros que fizerem ofensas, informando imediatamente a liderança.', true, 97) on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = excluded.is_published, updated_at = now();
