-- Clan Hub UPALELE: importação inicial idempotente do memorial e dos registros recebidos.
-- Confira o documento original antes de considerar o memorial publicado como versão oficial.
create unique index if not exists memorial_rules_section_number_uidx
on public.memorial_rules(section, rule_number) where rule_number is not null;

create table if not exists public.historical_punishment_records (
  id uuid primary key default gen_random_uuid(),
  source_order integer not null unique,
  member_name text not null,
  date_text text,
  notes text,
  source_label text not null default 'Histórico enviado pelo usuário',
  created_at timestamptz not null default now()
);
alter table public.historical_punishment_records enable row level security;
drop policy if exists "members read historical punishment records" on public.historical_punishment_records;
create policy "members read historical punishment records" on public.historical_punishment_records
for select to authenticated using (true);
drop policy if exists "leadership manages historical punishment records" on public.historical_punishment_records;
create policy "leadership manages historical punishment records" on public.historical_punishment_records
for all to authenticated using (public.is_clan_leadership()) with check (public.is_clan_leadership());

